/**
 * Emits the generated half of the Python SDK (`xos-sdk`): TypedDict models, the operation
 * table, one resource class per API resource and the `XosClient` that wires them together.
 * The output targets Python 3.9 and imports only the standard library and `xos_sdk._runtime`.
 */
import type { ApiIR, JsonSchema, OperationIR, SchemaIR } from "./ir.ts";
import { refName } from "./ir.ts";
import { isPythonKeyword, pascalCase, pythonIdentifier, snakeCase } from "./names.ts";
import type { EmittedFile } from "./ts-emitter.ts";

export const PYTHON_BANNER =
  "# Generated by @xos/sdk codegen from packages/api/openapi/v1.json. Do not edit; run `pnpm --filter @xos/sdk generate`.";

const CORE_MEMBERS = new Set(["base_url", "request", "request_page", "paginate"]);

function str(value: string): string {
  return JSON.stringify(value);
}

/** A Python literal for a JSON value. */
function pyLiteral(value: unknown): string {
  if (value === null) return "None";
  if (value === true) return "True";
  if (value === false) return "False";
  if (typeof value === "string") return str(value);
  if (typeof value === "number") return String(value);
  if (Array.isArray(value))
    return `(${value.map(pyLiteral).join(", ")}${value.length === 1 ? "," : ""})`;
  throw new Error(`No Python literal for ${JSON.stringify(value)}`);
}

function docstring(lines: readonly string[], indent: string): string {
  const text = lines
    .flatMap((l) => l.split("\n"))
    .map((l) => l.replace(/\\/g, "\\\\").replace(/"""/g, '\\"\\"\\"').trimEnd());
  while (text.length > 0 && text[text.length - 1] === "") text.pop();
  if (text.length === 0) return "";
  if (text.length === 1) return `${indent}"""${text[0]}"""\n`;
  return `${indent}"""${text[0]}\n${text
    .slice(1)
    .map((l) => (l ? `${indent}${l}` : ""))
    .join("\n")}\n${indent}"""\n`;
}

function commentLines(text: string | undefined, indent: string): string {
  if (!text) return "";
  return text
    .split("\n")
    .map((l) => `${indent}#: ${l}`.trimEnd())
    .join("\n")
    .concat("\n");
}

function isNullOnly(s: JsonSchema): boolean {
  const keys = Object.keys(s).filter((k) => k !== "description" && k !== "example");
  return (
    keys.length === 1 &&
    keys[0] === "type" &&
    (Array.isArray(s.type) ? s.type : [s.type]).includes("null")
  );
}

function union(members: readonly string[]): string {
  const unique = [...new Set(members)];
  const hasNone = unique.includes("None");
  const rest = unique.filter((m) => m !== "None");
  if (rest.length === 0) return "None";
  const inner = rest.length === 1 ? (rest[0] as string) : `Union[${rest.join(", ")}]`;
  return hasNone ? `Optional[${inner}]` : inner;
}

/**
 * Python annotation for a JSON Schema fragment. Every generated module uses postponed
 * evaluation of annotations, so model names need no quoting.
 */
export function pyType(s: JsonSchema): string {
  if (s.$ref) return refName(s.$ref);
  if (s.allOf) {
    const nullable = s.allOf.find(isNullOnly);
    const rest = s.allOf.filter((m) => m !== nullable);
    const inner = rest.length === 1 ? pyType(rest[0] as JsonSchema) : "Any";
    return nullable ? union([inner, "None"]) : inner;
  }
  const options = s.anyOf ?? s.oneOf;
  if (options) return union(options.map(pyType));
  if (s.enum) {
    const literals = s.enum.filter((v) => v !== null).map(pyLiteral);
    const lit = `Literal[${literals.join(", ")}]`;
    return s.enum.includes(null) ? `Optional[${lit}]` : lit;
  }
  const types =
    s.type === undefined
      ? s.properties
        ? ["object"]
        : []
      : Array.isArray(s.type)
        ? s.type
        : [s.type];
  if (types.length === 0) return "Any";
  return union(
    types.map((t) => {
      switch (t) {
        case "string":
          return "str";
        case "integer":
          return "int";
        case "number":
          return "float";
        case "boolean":
          return "bool";
        case "null":
          return "None";
        case "array":
          return `List[${s.items ? pyType(s.items) : "Any"}]`;
        case "object":
          return s.additionalProperties &&
            typeof s.additionalProperties === "object" &&
            !s.properties
            ? `Dict[str, ${pyType(s.additionalProperties)}]`
            : "Dict[str, Any]";
        default:
          throw new Error(`Unsupported JSON Schema type ${String(t)}`);
      }
    }),
  );
}

function isModelObject(s: JsonSchema): boolean {
  return (
    (s.type === "object" || (s.type === undefined && !!s.properties)) &&
    !!s.properties &&
    !s.allOf &&
    !s.anyOf
  );
}

function emitModel({ name, schema }: SchemaIR): string {
  const props = Object.entries(schema.properties ?? {});
  const required = new Set(schema.required ?? []);
  const doc = schema.description ? [schema.description] : [`The ${name} object.`];
  const keyword = props.some(([p]) => isPythonKeyword(p) || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(p));
  if (keyword) {
    const total = props.every(([p]) => required.has(p));
    const fields = props.map(([p, s]) => `    ${str(p)}: ${pyType(s)},`).join("\n");
    return `# ${doc[0]?.split("\n")[0] ?? name}\n${name} = TypedDict(\n    ${str(name)},\n    {\n${fields}\n    },\n    total=${total ? "True" : "False"},\n)\n`;
  }
  const field = ([p, s]: [string, JsonSchema]) =>
    `${commentLines(s.description, "    ")}    ${p}: ${pyType(s)}\n`;
  const req = props.filter(([p]) => required.has(p));
  const opt = props.filter(([p]) => !required.has(p));
  if (req.length === 0 || opt.length === 0) {
    const total = opt.length === 0 ? "" : ", total=False";
    return `class ${name}(TypedDict${total}):\n${docstring(doc, "    ")}${props.length ? "\n" + props.map(field).join("") : "    pass\n"}`;
  }
  return `class _${name}Required(TypedDict):\n${req.map(field).join("")}\n\nclass ${name}(_${name}Required, total=False):\n${docstring(doc, "    ")}\n${opt.map(field).join("")}`;
}

/** Orders type aliases so every alias is defined after the aliases it references. */
function sortAliases(aliases: readonly SchemaIR[]): SchemaIR[] {
  const byName = new Map(aliases.map((a) => [a.name, a]));
  const done = new Set<string>();
  const out: SchemaIR[] = [];
  const visit = (a: SchemaIR, stack: Set<string>) => {
    if (done.has(a.name)) return;
    if (stack.has(a.name)) throw new Error(`Alias cycle through ${a.name}`);
    stack.add(a.name);
    for (const m of JSON.stringify(a.schema).matchAll(/#\/components\/schemas\/([A-Za-z0-9]+)/g)) {
      const dep = byName.get(m[1] as string);
      if (dep) visit(dep, stack);
    }
    stack.delete(a.name);
    done.add(a.name);
    out.push(a);
  };
  for (const a of aliases) visit(a, new Set());
  return out;
}

function emitModels(ir: ApiIR): string {
  const objects = ir.schemas.filter((s) => isModelObject(s.schema));
  const aliases = sortAliases(ir.schemas.filter((s) => !isModelObject(s.schema)));
  const alias = ({ name, schema }: SchemaIR) =>
    `${commentLines(schema.description, "")}${name} = ${pyType(schema)}\n`;
  return `${PYTHON_BANNER}
"""Component schemas of the ${ir.title} as TypedDicts."""

from __future__ import annotations

from typing import Any, Dict, List, Literal, Optional, TypedDict, Union

__all__ = [
${ir.schemas.map((s) => `    ${str(s.name)},`).join("\n")}
]


${objects.map(emitModel).join("\n\n")}

${aliases.map(alias).join("\n")}`;
}

function emitOperations(ir: ApiIR): string {
  const entry = (op: OperationIR) => `    ${str(op.id)}: OperationSpec(
        id=${str(op.id)},
        resource=${str(op.resource)},
        verb=${str(op.verb)},
        method=${str(op.method)},
        path=${str(op.path)},
        path_params=${pyLiteral(op.pathParams.map((p) => p.name))},
        query_params=${pyLiteral(op.queryParams.map((p) => p.name))},
        required_query_params=${pyLiteral(op.queryParams.filter((p) => p.required).map((p) => p.name))},
        paged=${pyLiteral(op.paged)},
        fields=${pyLiteral(op.fields)},
        idempotent=${pyLiteral(op.idempotent)},
        if_match=${pyLiteral(op.ifMatch)},
        body=${pyLiteral(op.body)},
        body_required=${pyLiteral(op.bodyRequired)},
        success_status=${op.successStatus},
        response=${pyLiteral(op.response)},
        item=${pyLiteral(op.item)},
        tag=${str(op.tag)},
        summary=${str(op.summary)},
        capability=${pyLiteral(op.capability)},
        scopes=${pyLiteral(op.scopes)},
    ),`;
  return `${PYTHON_BANNER}
"""Every operation of the ${ir.title}, keyed by operation id."""

from __future__ import annotations

from typing import Dict, Tuple

from .._runtime.types import OperationSpec

#: Version of the OpenAPI document this SDK was generated from.
API_VERSION = ${str(ir.version)}
API_TITLE = ${str(ir.title)}

OPERATIONS: Dict[str, OperationSpec] = {
${ir.operations.map(entry).join("\n")}
}

#: Resources in document order: (resource name, module tag, operation ids).
RESOURCES: Tuple[Tuple[str, str, Tuple[str, ...]], ...] = (
${ir.resources.map((r) => `    (${str(r.name)}, ${str(r.tag)}, ${pyLiteral(r.operations.map((o) => o.id))}),`).join("\n")}
)
`;
}

function methodName(verb: string): string {
  const name = snakeCase(verb);
  return isPythonKeyword(name) ? `${name}_` : name;
}

function emitMethod(op: OperationIR, names: Set<string>, listAll: boolean): string {
  const base = methodName(op.verb);
  const name = listAll ? `${base}_all` : base;
  if (names.has(name))
    throw new Error(`${op.id}: Python method ${name} collides in ${op.resource}`);
  names.add(name);

  const positional: string[] = ["self"];
  const pathArgs: string[] = [];
  for (const p of op.pathParams) {
    const id = pythonIdentifier(p.name);
    const t = pyType(p.schema) === "int" ? "Union[int, str]" : "str";
    positional.push(`${id}: ${t}`);
    pathArgs.push(`${str(p.name)}: ${id}`);
  }
  if (op.body) {
    positional.push(op.bodyRequired ? `body: ${op.body}` : `body: Optional[${op.body}] = None`);
  }
  const keyword: string[] = [];
  const queryArgs: string[] = [];
  const requiredQuery = op.queryParams.filter((p) => p.required);
  const optionalQuery = op.queryParams.filter((p) => !p.required);
  for (const p of requiredQuery) {
    const id = pythonIdentifier(p.name);
    keyword.push(`${id}: ${pyType(p.schema)}`);
    queryArgs.push(`${str(p.name)}: ${id}`);
  }
  if (op.ifMatch) keyword.push("if_match: str");
  if (op.paged) {
    if (!listAll) keyword.push("limit: Optional[int] = None", "cursor: Optional[str] = None");
    else keyword.push("limit: Optional[int] = None");
    keyword.push(
      "fields: FieldsArg = None",
      "sort: SortArg = None",
      "filter: Optional[Filter] = None",
    );
    queryArgs.push(
      `"limit": limit`,
      ...(listAll ? [] : [`"cursor": cursor`]),
      `"fields": fields`,
      `"sort": sort`,
      `"filter": filter`,
    );
  } else if (op.fields) {
    keyword.push("fields: FieldsArg = None");
    queryArgs.push(`"fields": fields`);
  }
  for (const p of optionalQuery) {
    const id = pythonIdentifier(p.name);
    keyword.push(`${id}: Optional[${pyType(p.schema)}] = None`);
    queryArgs.push(`${str(p.name)}: ${id}`);
  }
  if (op.idempotent) keyword.push("idempotency_key: Optional[str] = None");
  keyword.push("options: Optional[RequestOptions] = None");

  const spec = `OPERATIONS[${str(op.id)}]`;
  const call: string[] = [spec];
  if (pathArgs.length) call.push(`path={${pathArgs.join(", ")}}`);
  if (queryArgs.length) call.push(`query={${queryArgs.join(", ")}}`);
  if (op.body) call.push("body=body");
  if (op.idempotent) call.push("idempotency_key=idempotency_key");
  if (op.ifMatch) call.push("if_match=if_match");
  call.push("options=options");

  let returns: string;
  let body: string;
  if (op.paged && listAll) {
    returns = `Iterator[${op.item}]`;
    body = `return self._client.paginate(${call.join(", ")})`;
  } else if (op.paged) {
    returns = `Page[${op.item}]`;
    body = `return self._client.request_page(${call.join(", ")})`;
  } else {
    returns = `ApiResponse[${op.response ?? "None"}]`;
    body = `return self._client.request(${call.join(", ")})`;
  }
  const params = [...positional, ...(keyword.length ? ["*", ...keyword] : [])];
  const doc = [op.summary, ""];
  if (op.description) doc.push(op.description, "");
  if (listAll) doc.push("Iterates every item across all pages, following ``next_cursor``.", "");
  doc.push(`\`\`${op.method} ${op.path}\`\` (operation \`\`${op.id}\`\`).`);
  if (op.capability) doc.push(`Requires the capability \`\`${op.capability}\`\`.`);
  return `    def ${name}(\n${params.map((p) => `        ${p},`).join("\n")}\n    ) -> ${returns}:\n${docstring(doc, "        ")}        ${body}\n`;
}

export function pyResourceClass(resource: string): string {
  return `${pascalCase(resource)}Resource`;
}

function usedModels(ir: ApiIR): string[] {
  const names = new Set<string>();
  for (const op of ir.operations) {
    for (const n of [op.body, op.item, op.response]) if (n) names.add(n);
    for (const p of [...op.pathParams, ...op.queryParams]) {
      for (const m of JSON.stringify(p.schema).matchAll(/#\/components\/schemas\/([A-Za-z0-9]+)/g))
        names.add(m[1] as string);
    }
  }
  const runtime = [
    "ApiResponse",
    "FieldsArg",
    "Filter",
    "Page",
    "RequestOptions",
    "SortArg",
    "Resource",
    "OPERATIONS",
  ];
  const clash = runtime.filter((n) => names.has(n));
  if (clash.length > 0)
    throw new Error(`Models collide with runtime names in resources.py: ${clash.join(", ")}`);
  return [...names].sort();
}

function emitResources(ir: ApiIR): string {
  const classes = ir.resources.map((r) => {
    const names = new Set<string>();
    const methods = r.operations.flatMap((op) => [
      emitMethod(op, names, false),
      ...(op.paged ? [emitMethod(op, names, true)] : []),
    ]);
    return `class ${pyResourceClass(r.name)}(Resource):\n${docstring([`Operations on \`\`${r.name}\`\`, in the ${r.tag} module.`], "    ")}\n${methods.join("\n")}`;
  });
  return `${PYTHON_BANNER}
"""One class per resource; every operation in the OpenAPI document is a method."""

from __future__ import annotations

from typing import TYPE_CHECKING, Iterator, List, Optional, Union

from .._runtime.client import Resource
from .._runtime.types import ApiResponse, FieldsArg, Filter, Page, RequestOptions, SortArg
from .operations import OPERATIONS

if TYPE_CHECKING:
    from .models import (
${usedModels(ir)
  .map((n) => `        ${n},`)
  .join("\n")}
    )


${classes.join("\n\n")}`;
}

function emitClient(ir: ApiIR): string {
  const attrs = ir.resources.map((r) => {
    const attr = methodName(r.name);
    if (CORE_MEMBERS.has(attr)) throw new Error(`Resource ${r.name} collides with a client member`);
    return { attr, cls: pyResourceClass(r.name), r };
  });
  return `${PYTHON_BANNER}
"""The generated client: one attribute per resource."""

from __future__ import annotations

from typing import Any

from .._runtime.client import XosClientCore
from .resources import (
${attrs.map((a) => `    ${a.cls},`).join("\n")}
)


class XosClient(XosClientCore):
    """Client for the ${ir.title} ${ir.version}.

    Example::

        from xos_sdk import XosClient

        xos = XosClient("https://atlas.example.com/api/v1", api_key=os.environ["XOS_API_KEY"])
        for project in xos.projects.list_all(filter={"project_state": {"eq": "Active"}}):
            print(project["name"])
    """

${attrs.map((a) => `    ${a.attr}: ${a.cls}`).join("\n")}

    def __init__(self, base_url: str, **kwargs: Any) -> None:
        super().__init__(base_url, **kwargs)
${attrs.map((a) => `        self.${a.attr} = ${a.cls}(self)`).join("\n")}
`;
}

/** The Python SDK files. */
export function emitPython(ir: ApiIR): EmittedFile[] {
  const root = "src/xos_sdk/_generated";
  return [
    {
      path: `${root}/__init__.py`,
      contents: `${PYTHON_BANNER}\n"""Generated modules. Import from \`\`xos_sdk\`\` instead."""\n`,
    },
    { path: `${root}/models.py`, contents: emitModels(ir) },
    { path: `${root}/operations.py`, contents: emitOperations(ir) },
    { path: `${root}/resources.py`, contents: emitResources(ir) },
    { path: `${root}/client.py`, contents: emitClient(ir) },
  ];
}
